window.VOCAB = [{"term": "Global Value Chains (GVCs)", "meaning": "Chuỗi giá trị toàn cầu", "definition": "The worldwide network of countries and firms involved in the different stages of making a product."}, {"term": "Production Fragmentation", "meaning": "Phân mảnh sản xuất", "definition": "Splitting a production process into separate stages carried out in different locations."}, {"term": "Offshoring", "meaning": "Dịch chuyển hoạt động ra nước ngoài", "definition": "Moving a business activity to another country."}, {"term": "Outsourcing", "meaning": "Thuê ngoài / gia công thuê ngoài", "definition": "Buying goods or services from an external supplier instead of producing them yourself."}, {"term": "Vertical Specialization", "meaning": "Chuyên môn hóa theo chiều dọc", "definition": "A narrow way of measuring how much production is split across borders."}, {"term": "Trade in Value-Added (TiVA)", "meaning": "Thương mại theo giá trị gia tăng", "definition": "Tracking trade by where value was actually added, not just where goods crossed a border."}, {"term": "Non-Tariff Barriers (NTBs)", "meaning": "Hàng rào phi thuế quan", "definition": "Government trade restrictions that are not simple import taxes."}, {"term": "Comparative Advantage", "meaning": "Lợi thế so sánh", "definition": "The idea that countries should specialize in what they produce relatively most efficiently, not necessarily best."}, {"term": "Absolute Advantage", "meaning": "Lợi thế tuyệt đối", "definition": "Being able to produce more of a good than another country using the same resources."}, {"term": "Opportunity Costs", "meaning": "Chi phí cơ hội", "definition": "What you give up by choosing one option over the next-best alternative."}, {"term": "Terms of Trade", "meaning": "Tỷ lệ trao đổi thương mại (tỷ giá thương mại)", "definition": "The rate at which a country's exports exchange for its imports."}, {"term": "Trade Liberalization", "meaning": "Tự do hóa thương mại", "definition": "Reducing government barriers to trade between countries."}, {"term": "Intra-Industry Trade", "meaning": "Thương mại nội ngành", "definition": "Trading similar goods within the same industry, in both directions."}, {"term": "Water Footprint", "meaning": "Dấu chân nước", "definition": "The total amount of water used, directly or indirectly, to produce what a country consumes or trades."}, {"term": "Carbon Footprint / Embodied Carbon", "meaning": "Dấu chân carbon / carbon hàm chứa", "definition": "The total greenhouse-gas emissions caused by making and transporting a traded good."}, {"term": "Heckscher-Ohlin Model", "meaning": "Mô hình Heckscher-Ohlin", "definition": "The trade theory explaining trade patterns through differences in factor endowments."}];